message.content:
{
  "sections": [
    {
      "title": "Why you were in the hospital",
      "bullets": [
        {
          "id": "b1",
          "text": "You had a lung infection called CAP in the lower right part of your lung.",
          "sources": ["p1:L5", "term:CAP"]
        },
        {
          "id": "b2",
          "text": "You also have Type 2 diabetes, which means high blood sugar.",
          "sources": ["p1:L5", "term:DM"]
        }
      ]
    },
    {
      "title": "What to do at home",
      "bullets": [
        {
          "id": "b3",
          "text": "Rest and slowly do more activity as you feel able.",
          "sources": ["p1:L13"]
        },
        {
          "id": "b4",
          "text": "Use your incentive spirometer 10 times each hour while you are awake.",
          "sources": ["p1:L13"]
        },
        {
          "id": "b5",
          "text": "Eat a carb‑consistent diabetic diet.",
          "sources": ["p1:L14"]
        },
        {
          "id": "b6",
          "text": "Drink plenty of fluids.",
          "sources": ["p1:L14"]
        }
      ]
    },
    {
      "title": "Your follow-up visits",
      "bullets": [
        {
          "id": "b7",
          "text": "See your primary care doctor. Go in 7 to 10 days. This visit checks your recovery.",
          "sources": ["p1:L15"]
        },
        {
          "id": "b8",
          "text": "Get a chest x‑ray. Go in 6 weeks. This test checks your lungs.",
          "sources": ["p1:L15"]
        }
      ]
    }
  ],
  "questions_for_your_doctor": [
    "How will I know if my lung infection is fully gone?",
    "What should my blood sugar targets be at home?",
    "When can I return to my normal exercise routine?"
  ]
}
